#!/usr/bin/env python3
"""omics/scrna_qc_pipeline — auto-generated run.py (archetype=omics_scrna).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "omics_scrna"
BRAIN = "omics"
SKILL = "scrna_qc_pipeline"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'scrna_qc_pipeline', 'matrix_path': '', 'n_cells_post_qc': 0, 'cluster_sizes': {}, 'marker_genes_per_cluster': {}, 'umap_png': '', 'diagnostics': {'brain': 'omics', 'archetype': 'omics_scrna'}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """Scanpy 单细胞 QC 流水线:read_10x → filter cells/genes → mt% → normalize → HVG → PCA → neighbors → leiden → UMAP。
    输入:matrix_dir (10x 格式)| h5ad_in / out_h5ad / min_genes / min_cells / mt_max
    """
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401
    matrix_dir = payload.get("matrix_dir")
    h5ad_in = payload.get("h5ad_in")
    out_h5ad = payload.get("out_h5ad") or _tempfile.NamedTemporaryFile(suffix="_qc.h5ad", delete=False).name
    min_genes = int(payload.get("min_genes", 200))
    min_cells = int(payload.get("min_cells", 3))
    mt_max = float(payload.get("mt_max_pct", 20))
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "tool": "scanpy", "out_h5ad": out_h5ad,
                   "min_genes": min_genes, "min_cells": min_cells, "mt_max": mt_max}
    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL, "matrix_path": "", "n_cells_post_qc": 0,
                "cluster_sizes": {}, "marker_genes_per_cluster": {}, "umap_png": "",
                "diagnostics": {**diagnostics, "dry": True}}
    if not matrix_dir and not h5ad_in:
        return {"ok": False, "error": "需要 matrix_dir (10x) 或 h5ad_in", "diagnostics": diagnostics}
    script = (
        "import json, sys, scanpy as sc\n"
        f"matrix_dir = {matrix_dir!r}; h5ad_in = {h5ad_in!r}; out_h5ad = {out_h5ad!r}\n"
        f"min_genes = {min_genes}; min_cells = {min_cells}; mt_max = {mt_max}\n"
        "ad = sc.read_10x_mtx(matrix_dir, var_names='gene_symbols') if matrix_dir else sc.read_h5ad(h5ad_in)\n"
        "sc.pp.filter_cells(ad, min_genes=min_genes)\n"
        "sc.pp.filter_genes(ad, min_cells=min_cells)\n"
        "ad.var['mt'] = ad.var_names.str.startswith(('MT-','mt-'))\n"
        "sc.pp.calculate_qc_metrics(ad, qc_vars=['mt'], inplace=True)\n"
        "ad = ad[ad.obs['pct_counts_mt'] < mt_max].copy()\n"
        "sc.pp.normalize_total(ad, target_sum=1e4); sc.pp.log1p(ad)\n"
        "sc.pp.highly_variable_genes(ad, n_top_genes=2000, flavor='seurat')\n"
        "sc.pp.scale(ad, max_value=10)\n"
        "sc.tl.pca(ad, n_comps=50)\n"
        "sc.pp.neighbors(ad, n_neighbors=15)\n"
        "sc.tl.umap(ad)\n"
        "sc.tl.leiden(ad, resolution=0.8)\n"
        "sc.tl.rank_genes_groups(ad, 'leiden', method='wilcoxon')\n"
        "ad.write_h5ad(out_h5ad)\n"
        "cluster_sizes = ad.obs['leiden'].value_counts().to_dict()\n"
        "markers = {c: list(ad.uns['rank_genes_groups']['names'][c][:10]) for c in cluster_sizes}\n"
        "json.dump({'matrix_path': out_h5ad, 'n_cells_post_qc': int(ad.n_obs),\n"
        "           'cluster_sizes': {str(k):int(v) for k,v in cluster_sizes.items()},\n"
        "           'marker_genes_per_cluster': markers}, sys.stdout)\n"
    )
    t0 = _time.time()
    r = run_tool(["python3", "-c", script], timeout=int(payload.get("timeout_s", 3600)))
    diagnostics["subprocess"] = {"wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "scanpy QC 失败"),
                "stderr": r.get("stderr", "")[-400:], "diagnostics": diagnostics}
    try:
        parsed = json.loads(r["stdout"])
    except json.JSONDecodeError as e:
        return {"ok": False, "error": f"stdout 解析失败: {e}", "stdout_head": r["stdout"][:300],
                "diagnostics": diagnostics}
    return {"ok": True, "skill_id": SKILL, **parsed, "umap_png": "",
            "runtime_sec": round(_time.time() - t0, 2), "diagnostics": diagnostics}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
